    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(i);
            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
